changeSet.sql:
-- ── Schema ────────────────────────────────────────────────────────────────────
ALTER TABLE medicine ALTER COLUMN clinic_id DROP NOT NULL;
DROP INDEX IF EXISTS idx_medicine_clinic_name_strength_mfg; CREATE UNIQUE INDEX IF NOT EXISTS idx_medicine_clinic_name_strength_mfg ON medicine ( COALESCE(clinic_id, 0), lower(name), lower(COALESCE(strength, '')), lower(COALESCE(manufacturer, '')) ) WHERE active = true;
-- ── Data cleanup (dev debt) ─────────────────────────────────────────────────── -- Remove per-clinic medicine copies that have no stock, no prescriptions, -- no sales — these are remnants of earlier seed-data experiments and carry -- zero value now that the platform catalog replaces them.
DELETE FROM medicine WHERE clinic_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM stock_batch WHERE medicine_id = medicine.id) AND NOT EXISTS (SELECT 1 FROM prescription_item WHERE medicine_id = medicine.id) AND NOT EXISTS (SELECT 1 FROM sale_item WHERE medicine_id = medicine.id);
-- ── Platform medicine catalog ───────────────────────────────────────────────── -- ~237 commonly dispensed medicines in India, grouped by therapeutic category. -- To add a new medicine: INSERT with clinic_id = NULL, ON CONFLICT DO NOTHING.
